    Bug 1980776 - For deleting/detaching attachments ensure CRLF message line endings to avoid imap server reporting "Message contains bare newlines". r=jtracey

    Differential Revision: https://phabricator.services.mozilla.com/D260639

diff --git a/mail/modules/AttachmentInfo.sys.mjs b/mail/modules/AttachmentInfo.sys.mjs
index 07b00796d66..2bfc53dc29c 100644
--- a/mail/modules/AttachmentInfo.sys.mjs
+++ b/mail/modules/AttachmentInfo.sys.mjs
@@ -809,7 +809,8 @@ export class AttachmentInfo {
           );
           return;
         }
-        resolve(this._data.join(""));
+        // We got the data. Ensure CRLF line endings.
+        resolve(this._data.join("").replace(/\r\n?|\n/g, "\r\n"));
       },
     };
